"// IMS IT Asset & Inventory Manager - Local & Global Access Server

const express = require('express');
const path = require('path');
const os = require('os');

const app = express();
const PORT = process.env.PORT || 3000;

// Serve static assets from the current directory
app.use(express.static(path.join(__dirname)));

// Route everything to index.html for Single Page Application
app.get('*', (req, res) => {
    res.sendFile(path.join(__dirname, 'index.html'));
});

// Start listening and print network addresses
app.listen(PORT, () => {
    console.log('\n=============================================================');
    console.log('      IMS IT ASSET & INVENTORY MANAGER - HOSTING ONLINE      ');
    console.log('=============================================================\n');
    console.log(`Local Machine Access:    http://localhost:${PORT}`);

    // Dynamically retrieve and display local network IP (Wi-Fi/Ethernet)
    const interfaces = os.networkInterfaces();
    let networkIp = null;

    for (const devName in interfaces) {
        const iface = interfaces[devName];
        for (let i = 0; i < iface.length; i++) {
            const alias = iface[i];
            if (alias.family === 'IPv4' && alias.address !== '127.0.0.1' && !alias.internal) {
                networkIp = alias.address;
                console.log(`Intranet Office Access:  http://${networkIp}:${PORT} (For other office devices)`);
            }
        }
    }

    console.log('\n-------------------------------------------------------------');
    console.log('GLOBAL WEB ACCESS (Anywhere in the world):');
    console.log('To securely share this active server globally, open a new terminal');
    console.log('inside this project directory and run:');
    console.log(`\n  npx localtunnel --port ${PORT}`);
    console.log('\nThis will output a public secure HTTPS URL you can share anywhere.');
    console.log('=============================================================\n');
});\
