"// Serve static assets from the current directory
app.use(express.static(path.join(__dirname)));

const https = require('https');

// Helper to make a secure POST request to kvdb.io to create an anonymous bucket
function fetchSyncTokenFromServer() {
    return new Promise((resolve, reject) => {
        const options = {
            hostname: 'kvdb.io',
            port: 443,
            path: '/',
            method: 'POST',
            headers: {
                'Content-Length': '0'
            }
        };

        const req = https.request(options, (res) => {
            let data = '';
            res.on('data', (chunk) => {
                data += chunk;
            });
            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    resolve(data.trim());
                } else {
                    reject(new Error(`Server responded with status code ${res.statusCode}`));
                }
            });
        });

        req.on('error', (e) => {
            reject(e);
        });

        req.end();
    });
}

// Endpoint to generate sync token (bypasses browser CORS policy)
app.post('/api/generate-sync-token', async (req, res) => {
    try {
        const token = await fetchSyncTokenFromServer();
        res.json({ token: token });
    } catch (error) {
        console.error('Error generating sync token on server:', error);
        res.status(500).json({ error: 'Failed to generate token from kvdb.io' });
    }
});

// Route everything to index.html for Single Page Application
app.get('*', (req, res) => {
    res.sendFile(path.join(__dirname, 'index.html'));
});"

