"function renderDashboardAlerts() {
    const container = DOM.alertsContainer;
    container.innerHTML = '';

    const today = new Date();
    const alerts = [];

    state.assets.forEach(asset => {
        if (!asset.warrantyExpiry) return;
        const expDate = new Date(asset.warrantyExpiry);
        const diffTime = expDate - today;
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (diffDays < 0) {
            alerts.push({
                type: 'danger', // Critical priority
                asset: asset,
                message: `Warranty EXPIRED on ${asset.warrantyExpiry}`,
                badge: 'Critical'
            });
        } else if (diffDays <= 90) {
            alerts.push({
                type: 'warning', // Warning priority
                asset: asset,
                message: `Warranty expiring in ${diffDays} days (${asset.warrantyExpiry})`,
                badge: 'Warning'
            });
        }
    });

    state.assets.forEach(asset => {
        if (asset.status === 'Maintenance') {
            alerts.push({
                type: 'info', // Maintenance priority
                asset: asset,
                message: `Currently offline undergoing maintenance`,
                badge: 'Maintenance'
            });
        }
    });

    if (alerts.length === 0) {
        container.innerHTML = `
            <div class="empty-state">
                <div class="empty-state-icon">🛡️</div>
                <p style="font-size: 13px;">No critical notifications. All device warranties and maintenance pipelines are green.</p>
